  function createSvg(el, def){
    const ns='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(ns,'svg');
    const classes=el.getAttribute('class'); if(classes) svg.setAttribute('class',classes);
    svg.setAttribute('viewBox', '0 0 '+def.w+' '+def.h);
    svg.setAttribute('aria-hidden','true'); svg.setAttribute('focusable','false');
    svg.setAttribute('fill','currentColor');
    const paths=Array.isArray(def.p)?def.p:[def.p];
    for(const p of paths){ const path=document.createElementNS(ns,'path'); path.setAttribute('d',p); svg.appendChild(path); }
    return svg;
  }
  window.lucide={
    createIcons(){
      document.querySelectorAll('[data-lucide]').forEach(el=>{
        const name=el.getAttribute('data-lucide'); const def=ICONS[name]; if(!def) return;
        const svg=createSvg(el,def); svg.setAttribute('data-icon',name); el.replaceWith(svg);
      });
    }
  };
